from collections import deque

def bfs(grafo, inicio):
    visitados = [inicio]
    fila = deque([inicio])
    while fila:
        atual = fila.popleft()
        for vizinho in grafo[atual]:
            if vizinho not in visitados:
                visitados.append(vizinho)
                fila.append(vizinho)
    return visitados

